
-- FIX 1: Tighten permissive RLS policies
DROP POLICY IF EXISTS "Anyone can insert email clicks" ON public.email_clicks;
CREATE POLICY "Validated email click inserts" ON public.email_clicks FOR INSERT WITH CHECK (send_id IS NOT NULL AND link_url IS NOT NULL AND length(link_url) <= 2048);

DROP POLICY IF EXISTS "Anyone can insert email opens" ON public.email_opens;
CREATE POLICY "Validated email open inserts" ON public.email_opens FOR INSERT WITH CHECK (send_id IS NOT NULL);

DROP POLICY IF EXISTS "Anyone can insert visits" ON public.landing_page_visits;
CREATE POLICY "Validated landing page visit inserts" ON public.landing_page_visits FOR INSERT WITH CHECK (session_id IS NOT NULL AND variant_id IS NOT NULL AND length(session_id) <= 255);

DROP POLICY IF EXISTS "Anyone can insert conversions" ON public.landing_page_conversions;
CREATE POLICY "Validated landing page conversion inserts" ON public.landing_page_conversions FOR INSERT WITH CHECK (visit_id IS NOT NULL AND variant_id IS NOT NULL AND conversion_type IS NOT NULL AND length(conversion_type) <= 100);

DROP POLICY IF EXISTS "Anyone can submit media inquiries" ON public.media_inquiries;
CREATE POLICY "Validated media inquiry inserts" ON public.media_inquiries FOR INSERT WITH CHECK (name IS NOT NULL AND length(name) <= 200 AND email IS NOT NULL AND length(email) <= 255 AND message IS NOT NULL AND length(message) <= 5000);

DROP POLICY IF EXISTS "Anyone can submit speaking requests" ON public.speaking_requests;
CREATE POLICY "Validated speaking request inserts" ON public.speaking_requests FOR INSERT WITH CHECK (organizer_name IS NOT NULL AND length(organizer_name) <= 200 AND organizer_email IS NOT NULL AND length(organizer_email) <= 255 AND event_type IS NOT NULL);

DROP POLICY IF EXISTS "Anyone can register for webinars" ON public.webinar_registrations;
CREATE POLICY "Validated webinar registration inserts" ON public.webinar_registrations FOR INSERT WITH CHECK (email IS NOT NULL AND length(email) <= 255 AND full_name IS NOT NULL AND length(full_name) <= 200 AND webinar_id IS NOT NULL);

-- FIX 2: Seed 5 additional objection cards
INSERT INTO public.objection_cards (claim_category, claim_text, sixty_second_response, five_minute_response, proof_breakdown_json, dialogue_questions, boundary_statement, prayer, scripture_refs, source_ids) VALUES
('portals', 'Stepping over the burning sands opens a spiritual portal', 'The "burning sands" is a metaphorical tradition referring to the journey of initiation, not a literal spiritual act. No verified theological source equates symbolic ceremony with spiritual portals. Scripture calls us to test claims (1 Thessalonians 5:21).', 'The phrase "burning sands" refers to the emotional journey of membership — a metaphor for perseverance. Critics conflate metaphorical language with literal spiritual acts, but this lacks both biblical and historical grounding.', '{"P": "The pledge process uses symbolic language common in many traditions.", "R": "Rituals are symbolic acts — the Bible is rich with ritual.", "O_oaths": "Commitments are character pledges, not spiritual covenants.", "O_obscurity": "Privacy does not equal occult secrecy.", "F": "Founders created organizations for uplift."}', ARRAY['Have you read the actual initiation materials?', 'What specific scripture addresses symbolic ceremony?', 'Can we distinguish between cultural tradition and spiritual worship?'], 'I respect your concern but cannot accept accusations based on assumptions rather than evidence.', 'Father, help me walk in truth and not in fear. Amen.', ARRAY['1 Thessalonians 5:21', 'Colossians 2:8', 'Romans 14:5'], ARRAY[]::uuid[]),
('oaths', 'Fraternity oaths are blood covenants that bind you to demons', 'Greek oaths are pledges of character and service — not blood covenants. A blood covenant in scripture (Genesis 15) involves literal shedding of blood. No mainstream Greek organization requires this.', 'The term "oath" in Greek life refers to a commitment to uphold values. These are moral commitments similar to wedding vows or military oaths. Conflating a character pledge with a demonic blood covenant is biblically inaccurate.', '{"P": "Moral commitments similar to faith-based oaths.", "R": "No ritual requires blood or invokes demonic entities.", "O_oaths": "Character oaths differ from biblical blood covenants.", "O_obscurity": "Oath content is private but not occult.", "F": "Founders designed oaths to build character."}', ARRAY['Have you read the actual oath text?', 'Do you apply the same concern to military oaths?', 'What distinguishes a character pledge from a spiritual covenant?'], 'I value your concern but ask that we examine actual content rather than assume the worst.', 'Lord, help me honor my commitments to You above all else. Amen.', ARRAY['Genesis 15:9-18', 'Hebrews 9:22', 'Matthew 5:37'], ARRAY[]::uuid[]),
('deity_names', 'Using names like Athena and Apollo means you worship false gods', 'Greek organizations use classical names as symbols of values — not as objects of worship. Using "Athena" to represent wisdom is no different than NASA naming a mission "Apollo."', 'Classical Greek names appear throughout civilization — universities, architecture, law, medicine, NASA. These are cultural references, not acts of worship. Paul himself engaged with Greek culture (Acts 17:22-28).', '{"P": "Symbolic meaning behind names — as values, not deities.", "R": "No ritual includes worship of Greek gods.", "O_oaths": "Oaths uphold values like scholarship and service.", "O_obscurity": "Classical name usage is public and well-documented.", "F": "Founders chose aspirational symbols following Western academic tradition."}', ARRAY['Do you believe NASA Apollo mission was pagan worship?', 'Is a hospital using the Rod of Asclepius idol worship?', 'Where do official materials require worship of these figures?'], 'Using a name as a symbol of a value is not the same as worshipping that figure.', 'Father, You are the source of all wisdom and excellence. Amen.', ARRAY['Acts 17:22-28', '1 Corinthians 8:4-6', 'Colossians 2:16-17'], ARRAY[]::uuid[]),
('secrecy', 'Secret handshakes prove it is an occult organization', 'Privacy and secrecy are not the same. Many wholesome organizations use private recognition signals. Early Christians used the ichthys as a private recognition sign during persecution.', 'Private recognition among members is ancient and widespread. Early Christians, military units, and medical boards all use private symbols or deliberations. The real question: does the private content require you to deny Christ? The answer is no.', '{"P": "Private elements build trust and identity.", "R": "Private symbols are a long tradition, including the early church.", "O_oaths": "Nothing requires spiritual allegiance beyond faith.", "O_obscurity": "Privacy builds trust and preserves tradition.", "F": "Founders valued discretion to protect members."}', ARRAY['Did you know early Christians used a secret fish symbol?', 'What is the difference between privacy and occult secrecy?', 'If you read the actual materials, would that change your view?'], 'I will not share private materials, just as I would not share private church elder discussions.', 'Lord, You see all things. Help me walk in integrity. Amen.', ARRAY['Proverbs 11:13', 'Matthew 6:6', 'Mark 4:11'], ARRAY[]::uuid[]),
('founders_masonry', 'All founders were Masons so Greek life is a Masonry pipeline', 'While some founders were Masons, this does not mean the organizations are Masonic pipelines. Many founders were also pastors and educators. Fraternal networks provided critical mutual aid during systemic exclusion.', 'In the early 20th century, Black Americans faced exclusion from mainstream insurance and professional networks. Some founders were Masons, but also pastors and scholars. Assuming a pipeline conflates correlation with causation.', '{"P": "The pledge process is distinct from Masonic initiation.", "R": "Greek rituals draw from academic traditions, not Masonic ceremonies.", "O_oaths": "Greek oaths are character pledges with different content than Masonic oaths.", "O_obscurity": "Some symbols overlap but shared symbolism does not equal shared purpose.", "F": "Founders lived where fraternal networks were survival tools, not conspiracies."}', ARRAY['Did you know fraternal orgs provided burial insurance when Black families were denied access?', 'If a founder was a church member, is the org a church pipeline?', 'What evidence connects current practices to Masonic recruitment?'], 'I reject the assumption that shared membership equals organizational conspiracy.', 'Father, help me honor those who built communities in the face of oppression. Amen.', ARRAY['Proverbs 18:15', 'Acts 17:11', 'Micah 6:8'], ARRAY[]::uuid[]);

-- FIX 3: Seed conversation scripts
INSERT INTO public.conversation_scripts (audience_type, scenario, opening_lines, key_points, questions_to_ask, boundary_statements, closing_prayer, source_ids) VALUES
('pastor', 'Pastor challenges Greek membership', 'Pastor, I respect your leadership. Can I share what I have learned?', ARRAY['My faith in Christ is my first commitment', 'I examined rituals through a biblical lens using PROOF', 'Nothing requires me to deny Christ', 'I value your counsel'], ARRAY['Have you read the initiation materials?', 'Can we look at scriptures together?', 'Would you hear from other pastors who are Greek?'], ARRAY['I will not accept being labeled compromised without evidence'], 'Lord, bless our conversation. Amen.', ARRAY[]::uuid[]),
('parent', 'Parent worried about Greek life', 'Mom/Dad, I want to show you how my faith and organization coexist.', ARRAY['Your faith foundation taught me to evaluate through scripture', 'I used PROOF to evaluate my organization', 'My involvement has deepened my faith', 'I am committed to Christ above any org'], ARRAY['What specific concerns do you have?', 'Would the PROOF framework help?', 'Can we pray together?'], ARRAY['I need you to trust I am walking with God'], 'Father, thank You for parents who care. Amen.', ARRAY[]::uuid[]),
('chapter', 'Chapter questions your faith', 'Hey family, being Greek and Christian are not in conflict for me.', ARRAY['Our founders built this on principles aligned with biblical values', 'Scholarship, service, and brotherhood are Christ-like', 'I share how faith informs my membership', 'We can be excellent Greeks AND Christians'], ARRAY['Have you explored founders faith backgrounds?', 'What would faith-informed service look like?', 'Anyone interested in studying how our values align with scripture?'], ARRAY['I respect diverse beliefs but ask respect for my faith'], 'God, use me as a light in my chapter. Amen.', ARRAY[]::uuid[]),
('spouse', 'Spouse feels Greek involvement competes with marriage', 'I hear you. You and our family come before any organization.', ARRAY['You are my first earthly priority', 'My involvement is about service, not secrecy', 'I am open to showing you our values', 'Let us set boundaries together'], ARRAY['What makes you feel this competes with us?', 'Would attending an open event help?', 'Can we set regular check-ins?'], ARRAY['I will not allow any org to damage our marriage'], 'Lord, protect our marriage. Amen.', ARRAY[]::uuid[]);

-- FIX 4: Seed study plans
INSERT INTO public.ai_study_plans (plan_type, title, description, proof_categories, days_json) VALUES
('7-day', 'PROOF Framework Foundations', 'A 7-day deep dive into each PROOF pillar.', ARRAY['P', 'R', 'O_oaths', 'O_obscurity', 'F'],
'[{"day":1,"title":"Introduction to PROOF","content":"Overview of the framework.","scripture":"1 Thessalonians 5:21","action":"Read PROOF overview and write your top 3 questions."},{"day":2,"title":"P — Pledge Process","content":"Examine the pledge process biblically.","scripture":"Colossians 2:8","action":"Compare org pledge values with Galatians 5:22-23."},{"day":3,"title":"R — Rituals","content":"Symbolic ritual vs spiritual worship.","scripture":"Romans 14:5-6","action":"List 3 faith rituals and compare to Greek rituals."},{"day":4,"title":"O — Oaths","content":"What Greek oaths actually say.","scripture":"Matthew 5:37","action":"Read your org oath and note any conflicts."},{"day":5,"title":"O — Obscurity","content":"Privacy vs harmful secrecy.","scripture":"Matthew 6:6","action":"Identify what is secret vs private."},{"day":6,"title":"F — Founders","content":"Historical context of Black Greek orgs.","scripture":"Proverbs 18:15","action":"Research one founder and their faith."},{"day":7,"title":"Integration","content":"Synthesize and commit to clarity.","scripture":"Joshua 24:15","action":"Write your personal statement."}]'::jsonb),
('30-day', 'Complete PROOF Mastery Journey', 'A 30-day comprehensive faith and Greek life journey.', ARRAY['P', 'R', 'O_oaths', 'O_obscurity', 'F'],
'[{"day":1,"title":"Why This Matters","content":"Understanding the tension.","scripture":"Romans 12:2","action":"Journal about when someone questioned your membership."},{"day":2,"title":"PROOF Overview","content":"Introduction to the framework.","scripture":"1 Thessalonians 5:21","action":"Complete the PROOF assessment."},{"day":3,"title":"Pledge Deep Dive","content":"Examining membership intake.","scripture":"Colossians 2:8","action":"Write your org core values."},{"day":4,"title":"Biblical Ritual","content":"Bible uses ritual for remembrance.","scripture":"1 Corinthians 11:24-25","action":"List 5 biblical rituals."},{"day":5,"title":"Greek Ritual in Context","content":"Comparing traditions.","scripture":"Romans 14:5-6","action":"Identify parallels."},{"day":6,"title":"Oaths in Scripture","content":"Bible on oaths.","scripture":"James 5:12","action":"Study Matthew 5:33-37."},{"day":7,"title":"Week 1 Reflection","content":"Review and integrate.","scripture":"Psalm 119:105","action":"Share an insight."},{"day":8,"title":"The Portal Myth","content":"Examining the portal claim.","scripture":"1 John 4:4","action":"Read the Clarity Coach response."},{"day":9,"title":"Deity Names","content":"Greek names in culture.","scripture":"Acts 17:22-28","action":"Find 5 examples."},{"day":10,"title":"Privacy vs Secrecy","content":"The distinction.","scripture":"Proverbs 11:13","action":"Write your definition."},{"day":11,"title":"Early Church Secrets","content":"Private symbols in early Christianity.","scripture":"Mark 4:11","action":"Research Disciplina Arcani."},{"day":12,"title":"Founders Faith","content":"Spiritual lives of founders.","scripture":"Hebrews 11:1","action":"Research founders who were ministers."},{"day":13,"title":"Historical Mutual Aid","content":"Fraternal networks as essential.","scripture":"Galatians 6:2","action":"Read about mutual aid."},{"day":14,"title":"Week 2 Reflection","content":"Midpoint review.","scripture":"Proverbs 4:7","action":"Retake the assessment."},{"day":15,"title":"Talking to Pastor","content":"Preparing the conversation.","scripture":"Proverbs 15:1","action":"Draft opening statement."},{"day":16,"title":"Talking to Family","content":"Parental concerns.","scripture":"Exodus 20:12","action":"Practice with Conversation Coach."},{"day":17,"title":"Talking to Chapter","content":"Faith witness in org.","scripture":"Matthew 5:16","action":"Bring faith to chapter."},{"day":18,"title":"Boundary Setting","content":"Healthy boundaries.","scripture":"Matthew 7:6","action":"Write 3 boundary statements."},{"day":19,"title":"Masonry Connection","content":"Examining claims.","scripture":"Acts 17:11","action":"Use Founders Guide."},{"day":20,"title":"Spiritual Discernment","content":"Developing practice.","scripture":"Hebrews 5:14","action":"Create evaluation checklist."},{"day":21,"title":"Week 3 Reflection","content":"Review.","scripture":"Philippians 1:6","action":"Journal perspective changes."},{"day":22,"title":"Anti-Hazing & Faith","content":"Hazing contradicts values.","scripture":"1 John 4:18","action":"Review anti-hazing policies."},{"day":23,"title":"Service as Worship","content":"Reframing service.","scripture":"James 2:17","action":"Plan a service project."},{"day":24,"title":"Financial Stewardship","content":"Managing dues faithfully.","scripture":"Luke 16:10-12","action":"Review finances."},{"day":25,"title":"Leadership & Faith","content":"Biblical leadership.","scripture":"Mark 10:43-45","action":"Apply a Christ-like principle."},{"day":26,"title":"Legacy Building","content":"Your legacy.","scripture":"Proverbs 13:22","action":"Write a vision statement."},{"day":27,"title":"Handling Criticism","content":"Responding with grace.","scripture":"1 Peter 3:15-16","action":"Practice 60-second response."},{"day":28,"title":"Community","content":"Building support.","scripture":"Proverbs 27:17","action":"Connect with another faith-Greek."},{"day":29,"title":"Your PROOF Statement","content":"Definitive statement.","scripture":"Joshua 24:15","action":"Write your complete statement."},{"day":30,"title":"Commissioning","content":"Go forward in clarity.","scripture":"2 Timothy 1:7","action":"Share your journey."}]'::jsonb);

-- FIX 5: Feedback table
CREATE TABLE IF NOT EXISTS public.worker_output_feedback (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  output_history_id UUID REFERENCES public.worker_output_history(id) ON DELETE CASCADE,
  user_id UUID NOT NULL,
  rating TEXT NOT NULL CHECK (rating IN ('helpful', 'not_helpful')),
  comment TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE public.worker_output_feedback ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Users insert own feedback" ON public.worker_output_feedback FOR INSERT WITH CHECK (auth.uid() = user_id);
CREATE POLICY "Users read own feedback" ON public.worker_output_feedback FOR SELECT USING (auth.uid() = user_id);
